def local_minima_indices(lst):
    n = len(lst)
    if n < 3:
        return []
    result = []
    for i in range(1, n - 1):
        if lst[i] < lst[i - 1] and lst[i] < lst[i + 1]:
            result.append(i)
    return result

def compress_consecutive_ranges(lst):
    if not lst:
        return []
    result = []
    start = lst[0]
    prev = lst[0]
    for x in lst[1:]:
        if x == prev + 1:
            prev = x
        else:
            result.append([start, prev])
            start = x
            prev = x
    result.append([start, prev])
    return result

def flatten_and_dedupe(nested):
    seen = set()
    result = []
    for sub in nested:
        for x in sub:
            if x not in seen:
                seen.add(x)
                result.append(x)
    return result

def split_on_sentinel(lst, sentinel):
    result = []
    current = []
    for x in lst:
        if x == sentinel:
            result.append(current)
            current = []
        else:
            current.append(x)
    result.append(current)
    return result

def intersperse(lst, sep):
    if len(lst) <= 1:
        return lst[:]
    result = []
    for i, x in enumerate(lst):
        if i > 0:
            result.append(sep)
        result.append(x)
    return result

def rotate_matrix_90(matrix):
    if not matrix:
        return []
    return [list(row) for row in zip(*matrix[::-1])]

def find_pairs_summing_to(lst, target):
    n = len(lst)
    result = []
    for i in range(n):
        for j in range(i + 1, n):
            if lst[i] + lst[j] == target:
                result.append([i, j])
    return result

def group_by_remainder(lst, n):
    result = {}
    for x in lst:
        key = x % n
        result.setdefault(key, []).append(x)
    return result

def sliding_window_average(lst, k):
    n = len(lst)
    if not isinstance(k, int) or isinstance(k, bool) or k <= 0 or k > n:
        return []
    result = []
    for i in range(n - k + 1):
        window = lst[i:i + k]
        avg = sum(window) / k
        result.append(round(avg, 4))
    return result

def index_of_max(lst):
    max_val = lst[0]
    max_idx = 0
    for i, x in enumerate(lst):
        if x > max_val:
            max_val = x
            max_idx = i
    return max_idx

def index_of_min(lst):
    min_val = lst[0]
    min_idx = 0
    for i, x in enumerate(lst):
        if x < min_val:
            min_val = x
            min_idx = i
    return min_idx

def alternate_sign(lst):
    result = []
    for i, x in enumerate(lst):
        if i % 2 == 0:
            result.append(abs(x))
        else:
            result.append(-abs(x))
    return result

def find_longest_common_prefix_length(a, b):
    n = min(len(a), len(b))
    count = 0
    for i in range(n):
        if a[i] == b[i]:
            count += 1
        else:
            break
    return count

def find_longest_common_suffix_length(a, b):
    n = min(len(a), len(b))
    count = 0
    for i in range(1, n + 1):
        if a[-i] == b[-i]:
            count += 1
        else:
            break
    return count

def chunk_by_sum_limit(lst, limit):
    result = []
    current = []
    current_sum = 0
    for x in lst:
        if current and current_sum + x > limit:
            result.append(current)
            current = [x]
            current_sum = x
        else:
            current.append(x)
            current_sum += x
    if current:
        result.append(current)
    return result

def interleave_multiple_lists(lists):
    result = []
    max_len = max((len(l) for l in lists), default=0)
    for i in range(max_len):
        for l in lists:
            if i < len(l):
                result.append(l[i])
    return result

def list_diff_multiset(a, b):
    from collections import Counter
    counts = Counter(b)
    result = []
    for x in a:
        if counts.get(x, 0) > 0:
            counts[x] -= 1
        else:
            result.append(x)
    return result

def chunked_reverse_order(lst, k):
    chunks = [lst[i:i + k] for i in range(0, len(lst), k)]
    result = []
    for chunk in reversed(chunks):
        result.extend(chunk)
    return result
